{%- set lines = [] -%}
{%- set by_code = {} -%}
{%- for d in doc.items if (d.confirmed_qty or 0) > 0 -%}
{%- set q = d.confirmed_qty -%}
{%- set sub = d.substitute_item_code if d.line_status == "Substituted" and d.substitute_item_code else None -%}
{%- set code = sub or d.item_code -%}
{%- if code in by_code -%}
{%- set r = by_code[code] -%}
{%- set _ = r.update({"qty": r.qty + q, "amount": r.amount + q * (d.confirmed_rate or 0)}) -%}
{%- else -%}
{%- set r = {"item_code": code, "qty": q, "rate": d.confirmed_rate, "amount": q * (d.confirmed_rate or 0),
    "supplier_part_no": frappe.db.get_value("Item Supplier", {"parent": sub, "supplier": doc.supplier}, "supplier_part_no") if sub else d.supplier_part_no,
    "retail_sku_suffix": frappe.db.get_value("Item", sub, "ifw_retailskusuffix") if sub else d.retail_sku_suffix,
    "description": frappe.db.get_value("Item", code, "description") or (frappe.db.get_value("Item", sub, "item_name") if sub else d.item_name)} -%}
{%- set _ = by_code.update({code: r}) -%}
{%- set _ = lines.append(r) -%}
{%- endif -%}
{%- endfor -%}
